public static void main(String[] args) throws Exception {
    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    String[] sa = br.readLine().split(" ");
    int n = Integer.parseInt(sa[0]);
    int q = Integer.parseInt(sa[1]);
    Obj[] arr = new Obj[n];
    sa = br.readLine().split(" ");
    for (int i = 0; i < n; i++) {
        Obj o = new Obj();
        o.a = Integer.parseInt(sa[i]);
        o.size = 1;
        arr[i] = o;
    }
    sa = br.readLine().split(" ");
    for (int i = 0; i < n; i++) {
        Obj o = arr[i];
        o.b = Integer.parseInt(sa[i]);
        o.v = o.a * o.b;
    }

    int mod = 998244353;
    LazySegTree<Obj, Obj> st = new LazySegTree<>(
            arr,
            new Obj(),
            (s1, s2) -> {
                Obj ret = new Obj();
                ret.a = (s1.a + s2.a) % mod;
                ret.b = (s1.b + s2.b) % mod;
                ret.v = (s1.v + s2.v) % mod;
                ret.size = s1.size + s2.size;
                return ret;
            },
            (f, s) -> {
                Obj ret = new Obj();
                ret.a = (s.a + f.a * s.size) % mod;
                ret.b = (s.b + f.b * s.size) % mod;
                ret.v = (s.v + s.a * f.b % mod + s.b * f.a % mod
                        + f.a * f.b % mod * s.size % mod) % mod; // Corrected line
                ret.size = s.size;
                return ret;
            },
            (f1, f2) -> {
                Obj ret = new Obj();
                ret.a = (f1.a + f2.a) % mod;
                ret.b = (f1.b + f2.b) % mod;
                return ret;
            },
            new Obj());

    PrintWriter pw = new PrintWriter(System.out);
    for (int i = 0; i < q; i++) {
        sa = br.readLine().split(" ");
        int t = Integer.parseInt(sa[0]);
        int l = Integer.parseInt(sa[1]) - 1;
        int r = Integer.parseInt(sa[2]);
        if (t == 1) {
            Obj f = new Obj();
            f.a = Integer.parseInt(sa[3]);
            st.apply(l, r, f);

        } else if (t == 2) {
            Obj f = new Obj();
            f.b = Integer.parseInt(sa[3]);
            st.apply(l, r, f);

        } else {
            Obj o = st.prod(l, r);
            pw.println(o.v);
        }
    }
    pw.flush();
    br.close();
}
